<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_role('washer');
$title='Antrian';
if(isset($_GET['start'])){$pdo->prepare("UPDATE transactions SET status='washing' WHERE id=? AND status='waiting'")->execute([(int)$_GET['start']]);header('Location:/washer/queue.php');exit;}
$rows=$pdo->query("SELECT t.*,c.name customer,v.plate_number,v.vehicle_type,s.name service FROM transactions t JOIN customers c ON c.id=t.customer_id JOIN vehicles v ON v.id=t.vehicle_id LEFT JOIN transaction_details td ON td.transaction_id=t.id LEFT JOIN services s ON s.id=td.service_id WHERE t.status='waiting' ORDER BY t.id")->fetchAll();require __DIR__.'/../includes/header.php';?><h2>Antrian Kendaraan</h2><div class="card"><div class="card-body"><table class="table"><tr><th>Invoice</th><th>Pelanggan</th><th>Kendaraan</th><th>Layanan</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['invoice_number']?></td><td><?=e($r['customer'])?></td><td><?=e($r['plate_number'])?> (<?=$r['vehicle_type']?>)</td><td><?=e($r['service'])?></td><td><a class="btn btn-sm btn-primary" href="?start=<?=$r['id']?>">Mulai Cuci</a></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
